-- SELECT-only restoration inventory. No personnel/file bytes are read.
select 'competency_reference' kind, coalesce(jsonb_agg(to_jsonb(t) order by sort_order,code),'[]') data from public.competency_types t
union all select 'reminder_setting',coalesce(jsonb_agg(to_jsonb(s)),'[]') from public.app_settings s where key='competency.reminder_days'
union all select 'bucket',coalesce(jsonb_agg(to_jsonb(b)),'[]') from storage.buckets b where id='certificates'
union all select 'table_columns',jsonb_agg(jsonb_build_object('table',c.table_name,'ordinal',c.ordinal_position,'name',c.column_name,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) order by c.table_name,c.ordinal_position)
from information_schema.columns c join pg_attribute a on a.attrelid=('public.'||c.table_name)::regclass and a.attname=c.column_name left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum
where c.table_schema='public' and c.table_name in ('staff_members','staff_competencies','competency_types','emergency_drills')
union all select 'constraints',jsonb_agg(jsonb_build_object('table',conrelid::regclass::text,'name',conname,'sql',pg_get_constraintdef(oid))) from pg_constraint where conrelid in ('public.staff_members'::regclass,'public.staff_competencies'::regclass,'public.competency_types'::regclass,'public.emergency_drills'::regclass)
union all select 'indexes',jsonb_agg(pg_get_indexdef(i.indexrelid)) from pg_index i where i.indrelid in ('public.staff_members'::regclass,'public.staff_competencies'::regclass,'public.competency_types'::regclass,'public.emergency_drills'::regclass) and not exists(select 1 from pg_constraint c where c.conindid=i.indexrelid)
union all select 'triggers',jsonb_agg(pg_get_triggerdef(oid)) from pg_trigger where not tgisinternal and tgrelid in ('public.staff_members'::regclass,'public.staff_competencies'::regclass,'public.emergency_drills'::regclass)
union all select 'enums',jsonb_agg(jsonb_build_object('name',t.typname,'label',e.enumlabel) order by t.typname,e.enumsortorder) from pg_type t join pg_enum e on e.enumtypid=t.oid where t.oid in ('public.staff_category'::regtype,'public.competency_state'::regtype)
union all select 'relation_acl',jsonb_agg(jsonb_build_object('name',c.relname,'rls',c.relrowsecurity,'acl',c.relacl,'options',c.reloptions,'grants',(select jsonb_agg(jsonb_build_object('role',case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,'privilege',a.privilege_type,'grantable',a.is_grantable)) from aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a))) from pg_class c where c.oid in ('public.staff_members'::regclass,'public.staff_competencies'::regclass,'public.competency_types'::regclass,'public.emergency_drills'::regclass,'public.v_staff_competency_status'::regclass,'public.v_center_competency_readiness'::regclass)
union all select 'function_acl',jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'grants',(select jsonb_agg(jsonb_build_object('role',case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,'privilege',a.privilege_type,'grantable',a.is_grantable)) from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a))) from pg_proc p where p.oid in ('app.fill_competency_expiry()'::regprocedure,'public.notify_expiring_competencies()'::regprocedure);
